import{_ as n,l as r,o as e,c as d,v as i,p as l,x as o,d as s,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"Diamond–Dybvig 挤兑","description":"","frontmatter":{"title":"Diamond–Dybvig 挤兑","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/diamond-dybvig.md","filePath":"econ/diamond-dybvig.md","lastUpdated":1789023840000}'),m={name:"econ/diamond-dybvig.md"};function h(c,a,D,A,_,b){const t=r("Mermaid");return e(),d("div",null,[a[1]||(a[1]=i('<h1 id="diamond–dybvig-挤兑" tabindex="-1">Diamond–Dybvig 挤兑 <a class="header-anchor" href="#diamond–dybvig-挤兑" aria-label="Permalink to &quot;Diamond–Dybvig 挤兑&quot;">​</a></h1><div class="epigraph"><p>活期存款把流动性保险写成可执行的合同；同一合同在序贯兑付下也可以是挤兑。</p><footer>—— Diamond and Dybvig, Bank Runs, Deposit Insurance, and Liquidity, Journal of Political Economy 1983</footer></div><p><a href="/econ/stiglitz-weiss">上一课</a>（信贷配给 Stiglitz–Weiss）。<a href="/econ/why-intermediaries">金融中介的功能</a>。Gurley–Shaw 已经把银行钉成流动性转换器；本课缺口是把「转换」收成一个可算的存款合同，并证明它同时允许好均衡与挤兑。不从货币史或恐慌故事起笔。附录原文对照见 <a href="/econ/diamond-dybvig-paper">Diamond–Dybvig 原文</a>，主干只取机制。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>上一课的流动性转换若只写成「短借长贷」，还没有说明：为什么不让每个家庭自己持有那项长技术、需要时再卖出。答案必须是：个人面对的流动性冲击不可保于市场上，而银行可以用活期存款做<strong>风险分担</strong>。可一旦存款可随时按约定额度提取，保险合同自己会制造第二均衡——人人提款，长期技术被清算，后到的人什么都拿不到。</p><p>Diamond 与 Dybvig（1983）的设定是三期。\\(t=0\\) 投资一项不可逆技术，在 \\(t=2\\) 成熟；若在 \\(t=1\\) 中断，只能拿回较低的清算值。代理人在 \\(t=1\\) 才知道自己是急躁（只在 \\(t=1\\) 消费）还是耐心（可等到 \\(t=2\\)）。冲击私有，不可在 \\(t=0\\) 用<a href="/econ/state-contingent">或有要求权</a>直接写进证券——因为状态是个人的，不是可验证的公共状态。缺口因此是：有没有一种存款合同，在没有挤兑时实现最优保险，同时必须面对挤兑。</p><p><span class="marginnote">技术在 \\(t=1\\) 的清算值小于 1，成熟值大于 1。这不是「银行经营不善」，而是流动性本身有成本。挤兑可以发生在资产质量并未恶化之时。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>银行在 \\(t=0\\) 吸收存款、投资该技术，并承诺一套活期合同：在 \\(t=1\\) 提款得到 \\(r_1\\)，留下的人在 \\(t=2\\) 按剩余资产分配。\\(r_1\\) 选在急躁者的最优保险水平上，通常 \\(r_1\\gt 1\\) 的清算份额，从而耐心者补贴急躁者——这正是相对于自给自足的收益。</p><p>关键约束是<strong>序贯服务</strong>：银行按到达次序兑付，不知道也不等待「今天一共有多少人要提」。耐心者看到别人排长队时，最优反应可能是也去排。于是存在两个纯策略纳什均衡。好均衡：只有急躁者在 \\(t=1\\) 提，耐心者等到 \\(t=2\\)，保险实现。坏均衡：所有人在 \\(t=1\\) 提，资产被清算光，后到者得零——这就是挤兑。坏均衡可以由与基本面无关的太阳黑子触发。</p>',10)),(e(),l(E,null,{default:o(()=>[p(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEP%5B%22%E6%B4%BB%E6%9C%9F%E5%AD%98%E6%AC%BE%E5%90%88%E5%90%8C%20r1%22%5D%20--%3E%20GOOD%5B%22%E5%A5%BD%E5%9D%87%E8%A1%A1%3A%20%E4%BB%85%E6%80%A5%E8%BA%81%E8%80%85%E6%8F%90%22%5D%0A%20%20DEP%20--%3E%20RUN%5B%22%E5%9D%8F%E5%9D%87%E8%A1%A1%3A%20%E4%BA%BA%E4%BA%BA%E6%8F%90%22%5D%0A%20%20GOOD%20--%3E%20INS%5B%22%E6%B5%81%E5%8A%A8%E6%80%A7%E4%BF%9D%E9%99%A9%E5%AE%9E%E7%8E%B0%22%5D%0A%20%20RUN%20--%3E%20LIQ%5B%22%E6%8F%90%E5%89%8D%E6%B8%85%E7%AE%97%E9%95%BF%E6%9C%9F%E6%8A%80%E6%9C%AF%22%5D%0A%20%20SEQ%5B%22%E5%BA%8F%E8%B4%AF%E6%9C%8D%E5%8A%A1%22%5D%20--%3E%20RUN%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<p>存款保险或暂停兑付可以去掉坏均衡：若耐心者相信自己在 \\(t=2\\) 仍能拿到合同所允，就不必加入队列。1983 年的政策含义写在标题里：保险与流动性是同一件家具的两面。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制不是「谣言让人变傻」，而是合同与信息结构。活期存款把保险写进可在 \\(t=1\\) 执行的权利；序贯服务使执行变成先到先得的配给。先到者拿走的是面值，不是按比例的清算份额，于是外部效应出现：我的提取降低你能拿到的剩余。耐心者的提款决策于是取决于对他人提款的信念，信念可以自实现。</p><p>这与<a href="/econ/akerlof-lemons">柠檬市场</a>不同：资产质量可以完全透明，挤兑仍然发生。也与<a href="/econ/moral-hazard">道德风险</a>不同：银行可以没有隐藏行动。Diamond–Dybvig 的银行可以是被动的资产池；脆弱性来自负债合同，不来自经理卸责。后课的<a href="/econ/lender-of-last-resort">最后贷款人</a>要处理的，正是这种与偿付能力可分离的流动性崩溃。</p><h3 id="保险合同为什么必须是活期" tabindex="-1">保险合同为什么必须是活期 <a class="header-anchor" href="#保险合同为什么必须是活期" aria-label="Permalink to &quot;保险合同为什么必须是活期&quot;">​</a></h3><p>若合同改成「\\(t=1\\) 只按急躁者的真实比例结算」，最优保险仍可写，但那要求类型可验证或银行能等到全部申报。私有冲击下，活期加序贯是把保险做成无需验证的权利：你来取，就按 \\(r_1\\) 付。权利一旦无条件，排队就有价值。暂停兑付等于临时取消这权利；存款保险等于用财政或保险基金对 \\(r_1\\) 与 \\(t=2\\) 支付作保。两者都改变博弈，而不是给银行「更多准备金」——模型里还没有准备金。</p><p>加总确定性（急躁者比例已知）使好均衡的资源约束是确定的。后来的文献让比例随机，挤兑可以有基本面触发；主干不把那一层提前。太阳黑子在这里的资格是：合同允许坏均衡，选择可以与技术无关。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>模型是真实的三期一般均衡，没有法定货币、没有准备金账户。因此它解释挤兑与保险，不解释货币如何被「创造」——那是<a href="/econ/reserve-endogenous-money">内生货币</a>的缺口。也不要把太阳黑子挤兑读成唯一故事：后来的文献引入资产基本面恶化作为挤兑的触发；主干在此只钉「合同允许坏均衡」。</p><p>序贯服务是建模选择。若银行能按比例暂停、或能观测总需求再结算，坏均衡可以被设计掉。现实中的 ATM、日内结算接近序贯；破产程序里的冻结接近暂停。政策工具的对照放到附录原文课，本课只保留：保险合同与挤兑合同是同一张存款单。</p><p>也不要把批发融资挤兑、货币市场基金赎回直接写成 1983 年的定理。那些是同一转换功能换了一张负债合同；机制同构，文献不是同一篇。附录 <a href="/econ/diamond-dybvig-paper">Diamond–Dybvig 原文</a> 对照页码与激励相容，不在主干再抄一遍证明。</p><p>后课默认：活期存款同时是保险与挤兑合同；坏均衡不要求资产先坏。准备金、窗口、资本都是后来叠上去的约束。</p><p>太阳黑子在这里的资格是：合同允许坏均衡，选择可以与技术无关。基本面触发是后继，不是本课唯一故事。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>活期存款在不可验证的个人流动性冲击下实施保险。</li><li>序贯服务使同一合同具有挤兑均衡；挤兑不必有资产恶化。</li><li>存款保险或暂停兑付的作用是删掉坏均衡，不是给银行送资本。</li><li>真实模型，尚未引入准备金与法定货币。</li><li>出处：Diamond and Dybvig, <em>JPE</em> 1983。</li></ul>',15))])}const u=n(m,[["render",h]]);export{g as __pageData,u as default};
